const getRawMaterials = async (req, res, next) => {
    try {
        const targetCategory = req.body?.filter?.category;
        const query = targetCategory ? { category: targetCategory } : {};
        const materials = await RawMaterial.find(query).sort({ createdAt: -1 });
        res.status(200).json(materials);
    } catch (error) {
        next(error);
    }
};
